options.customCss:
@import url('https://fonts.googleapis.com/css2?family=Orbitron:wght@700;900&family=Fira+Code:wght@400;600&family=Chakra+Petch:wght@500&display=swap');

:root {
  --chat--color-primary: #00ffff;
  --chat--color-primary-shade-50: #00e6e6;
  --chat--color-primary-shade-100: #00cccc;
  --chat--color-secondary: #ff00ff;
  --chat--color-secondary-shade-50: #e600e6;
  --chat--color-white: #f0f8ff;
  --chat--color-light: #d1f7ff;
  --chat--color-dark: #0a0218;
  --chat--color-disabled: #3a3a3a;
  --chat--color-typing: var(--chat--color-primary);
  --chat--border-color-glow: rgba(0, 255, 255, 0.5);
  --chat--spacing: 1rem;
  --chat--border-radius: 1.5rem;
  --chat--font-family: 'Fira Code', 'Chakra Petch', sans-serif;
  --chat--font-family-headings: 'Orbitron', sans-serif;
  --chat--transition-duration: 0.4s;
  --chat--window--width: 480px;
  --chat--window--height: 85vh;
  --chat--window--bottom: 2rem;
  --chat--window--right: 2rem;
  --chat--window--z-index: 9999;
  --chat--window--border: 2px solid transparent;
  --chat--window--border-radius: var(--chat--border-radius);
  --chat--window--margin-bottom: var(--chat--spacing);
  --chat--body--background: #0a0218;
  --chat--footer--background: rgba(10, 2, 24, 0.8);
  --chat--header--background: linear-gradient(135deg, var(--chat--color-secondary), #1e0033 50%, var(--chat--color-primary));
  --chat--header--color: var(--chat--color-white);
  --chat--heading--font-size: 1.8em;
  --chat--subtitle--font-size: 0.9em;
  --chat--header--border-bottom: 1px solid var(--chat--border-color-glow);
  --chat--message--font-size: 1rem;
  --chat--message--padding: 1rem 1.5rem;
  --chat--message--border-radius: 1.2rem;
  --chat--message-line-height: 1.6;
  --chat--message--margin-bottom: 1rem;
  --chat--message--bot--background: rgba(20, 20, 40, 0.6);
  --chat--message--bot--color: var(--chat--color-light);
  --chat--message--user--background: linear-gradient(135deg, var(--chat--color-primary), var(--chat--color-secondary));
  --chat--message--user--color: #ffffff;
  --chat--messages-list--padding: 1.5rem;
  --chat--input--background: rgba(0, 0, 0, 0.4);
  --chat--input--text-color: var(--chat--color-white);
  --chat--input--border-radius: 1rem;
  --chat--input--padding: 1rem;
  --chat--textarea--height: 55px;
  --chat--button--background: linear-gradient(135deg, var(--chat--color-primary), var(--chat--color-secondary));
  --chat--button--color: var(--chat--color-white);
  --chat--button--border-radius: 1rem;
  --chat--button--hover--background: linear-gradient(135deg, var(--chat--color-secondary), var(--chat--color-primary));
  --chat--input--send--button--color: var(--chat--color-primary);
  --chat--input--send--button--color-hover: var(--chat--color-secondary);
  --chat--toggle--size: 70px;
  --chat--toggle--border-radius: 50%;
  --chat--toggle--background: linear-gradient(145deg, var(--chat--color-primary), var(--chat--color-secondary));
  --chat--toggle--hover--background: linear-gradient(145deg, var(--chat--color-secondary), var(--chat--color-primary));
  --chat--toggle--color: var(--chat--color-white);
}

.chat-window {
  border-radius: var(--chat--window--border-radius);
  overflow: hidden;
  background: var(--chat--body--background);
  animation: fadeInGlow 1.2s ease-out forwards;
  position: relative;
  box-shadow: 0 0 100px rgba(0, 255, 255, 0.4), 0 0 120px rgba(255, 0, 255, 0.3);
  display: flex;
  flex-direction: column;
}

.chat-window::before {
  content: '';
  position: absolute;
  top: -50%;
  left: -50%;
  width: 200%;
  height: 200%;
  background: conic-gradient(transparent, var(--chat--border-color-glow), transparent 30%);
  animation: rotate-border 6s linear infinite;
  z-index: 1;
}

.chat-window::after {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-image: repeating-linear-gradient(0deg, rgba(0, 255, 255, 0.05), rgba(0, 255, 255, 0.05) 1px, transparent 1px, transparent 20px), repeating-linear-gradient(90deg, rgba(0, 255, 255, 0.05), rgba(0, 255, 255, 0.05) 1px, transparent 1px, transparent 20px);
  animation: background-pan 60s linear infinite;
  z-index: 0;
  opacity: 0.5;
}

.chat-header {
  font-family: var(--chat--font-family-headings);
  text-shadow: 0 0 8px var(--chat--color-primary), 0 0 12px var(--chat--color-primary), 0 0 20px var(--chat--color-secondary);
  position: relative;
  background: var(--chat--header--background);
  color: var(--chat--header--color);
  padding: 1.5rem;
  border-bottom: var(--chat--header--border-bottom);
  text-align: center;
  letter-spacing: 3px;
  animation: neon-flicker 4s infinite alternate;
  z-index: 2;
  border-top-left-radius: var(--chat--window--border-radius);
  border-top-right-radius: var(--chat--window--border-radius);
}

.chat-header::after {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 200%;
  background-image: linear-gradient(0deg, transparent 50%, rgba(10, 2, 26, 0.5) 50%);
  background-size: 100% 6px;
  opacity: 0.2;
  animation: scanline 8s linear infinite;
}

.chat-messages-list {
    flex-grow: 1;
    overflow-y: auto;
    padding: var(--chat--messages-list--padding);
    z-index: 2;
}

.chat-message {
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  max-width: 85%;
  transition: all var(--chat--transition-duration) cubic-bezier(0.165, 0.84, 0.44, 1);
  animation: slideUpFade 0.7s ease-out forwards;
  opacity: 0;
  transform: translateY(20px);
  animation-fill-mode: forwards;
}

.chat-messages-list .chat-message:nth-child(1) { animation-delay: 0.1s; }
.chat-messages-list .chat-message:nth-child(2) { animation-delay: 0.2s; }
.chat-messages-list .chat-message:nth-child(3) { animation-delay: 0.3s; }
.chat-messages-list .chat-message:nth-child(4) { animation-delay: 0.4s; }


.chat-message:hover {
  transform: translateY(-5px) scale(1.02);
  filter: brightness(1.25);
}

.chat-message-user {
  background: var(--chat--message--user--background);
  color: var(--chat--message--user--color);
  border-radius: 1.2rem 1.2rem 0.2rem 1.2rem;
  box-shadow: 0 0 25px rgba(0, 255, 255, 0.4);
  animation: user-message-pulse 2.5s infinite;
}

.chat-message-bot {
  background: var(--chat--message--bot--background);
  color: var(--chat--message--bot--color);
  border: 1px solid var(--chat--border-color-glow);
  border-radius: 1.2rem 1.2rem 1.2rem 0.2rem;
  box-shadow: 0 4px 30px rgba(0, 0, 0, 0.5);
  position: relative;
  overflow: hidden;
}

.chat-message-bot::after {
    content: '';
    position: absolute;
    top: -50%;
    left: -100%;
    width: 200%;
    height: 200%;
    background: linear-gradient(110deg, transparent 40%, rgba(255, 255, 255, 0.1) 50%, transparent 60%);
    transform: rotate(25deg);
    animation: glass-shine 5s infinite;
}

.chat-typing {
  display: flex;
  align-items: center;
  padding: 10px;
}
.chat-typing span {
  height: 10px;
  width: 10px;
  margin: 0 4px;
  background-color: var(--chat--color-primary);
  border-radius: 50%;
  opacity: 0.4;
  animation: typing-dots 1.4s infinite;
  box-shadow: 0 0 8px var(--chat--color-primary);
}
.chat-typing span:nth-child(2) { animation-delay: 0.2s; }
.chat-typing span:nth-child(3) { animation-delay: 0.4s; }

.chat-footer {
    background: var(--chat--footer--background);
    padding: var(--chat--spacing);
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
    z-index: 2;
    border-bottom-left-radius: var(--chat--window--border-radius);
    border-bottom-right-radius: var(--chat--window--border-radius);
}

.chat-input {
  background-image: linear-gradient(var(--chat--input--background), var(--chat--input--background)),
                    linear-gradient(100deg, var(--chat--color-secondary), var(--chat--color-primary), var(--chat--color-secondary));
  background-origin: border-box;
  background-clip: padding-box, border-box;
  border: 2px solid transparent;
  background-size: 200% 100%;
  animation: move-border 4s linear infinite;
  color: var(--chat--input--text-color);
  height: var(--chat--textarea--height);
  padding: var(--chat--input--padding);
  border-radius: var(--chat--input--border-radius);
  width: 100%;
  transition: all 0.3s ease;
}
.chat-input:focus {
    outline: none;
    box-shadow: 0 0 25px var(--chat--color-primary), inset 0 0 20px rgba(0, 255, 255, 0.25);
}

.chat-toggle {
  width: var(--chat--toggle--size);
  height: var(--chat--toggle--size);
  border-radius: var(--chat--toggle--border-radius);
  background: var(--chat--toggle--background);
  color: var(--chat--toggle--color);
  box-shadow: 0 0 35px rgba(0, 255, 255, 0.7), 0 0 45px rgba(255, 0, 255, 0.5);
  transition: all var(--chat--transition-duration) ease-in-out;
  animation: float 4s infinite ease-in-out;
  border: 2px solid var(--chat--color-primary);
}

.chat-toggle:hover {
  background: var(--chat--toggle--hover--background);
  box-shadow: 0 0 55px rgba(255, 0, 255, 0.8), 0 0 65px rgba(0, 255, 255, 0.6);
  transform: scale(1.1) rotate(-15deg);
  animation-play-state: paused;
}

.chat-messages-list::-webkit-scrollbar { width: 10px; }
.chat-messages-list::-webkit-scrollbar-track { background: transparent; }
.chat-messages-list::-webkit-scrollbar-thumb {
  background: var(--chat--color-primary);
  border-radius: 10px;
  box-shadow: 0 0 12px var(--chat--color-primary);
  border: 2px solid var(--chat--color-dark);
}
.chat-messages-list::-webkit-scrollbar-thumb:hover { background: var(--chat--color-secondary); box-shadow: 0 0 16px var(--chat--color-secondary); }

@keyframes animated-gradient {
  0% { background-position: 0% 50%; }
  50% { background-position: 100% 50%; }
  100% { background-position: 0% 50%; }
}
@keyframes rotate-border { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }
@keyframes move-border { from { background-position: 0% 0%; } to { background-position: 200% 0%; } }
@keyframes fadeInGlow {
  from { opacity: 0; transform: scale(0.95); box-shadow: 0 0 20px rgba(0, 255, 255, 0.2); }
  to { opacity: 1; transform: scale(1); box-shadow: 0 0 100px rgba(0, 255, 255, 0.4), 0 0 120px rgba(255, 0, 255, 0.3); }
}
@keyframes slideUpFade {
  from { opacity: 0; transform: translateY(20px); }
  to { opacity: 1; transform: translateY(0); }
}
@keyframes user-message-pulse {
  0% { box-shadow: 0 0 25px rgba(0, 255, 255, 0.4); }
  50% { box-shadow: 0 0 40px rgba(255, 0, 255, 0.5), 0 0 15px var(--chat--color-secondary) inset; }
  100% { box-shadow: 0 0 25px rgba(0, 255, 255, 0.4); }
}
@keyframes neon-flicker {
    0%, 100% { text-shadow: 0 0 5px var(--chat--color-primary), 0 0 10px var(--chat--color-primary), 0 0 20px var(--chat--color-secondary), 0 0 40px var(--chat--color-secondary); }
    50% { text-shadow: 0 0 10px var(--chat--color-primary), 0 0 20px var(--chat--color-primary-shade-50), 0 0 30px var(--chat--color-secondary-shade-50), 0 0 50px var(--chat--color-secondary); }
}
@keyframes glass-shine {
    0% { left: -150%; }
    100% { left: 150%; }
}
@keyframes typing-dots {
  0%, 75%, 100% { transform: translateY(0); opacity: 0.4; }
  25% { transform: translateY(-8px); opacity: 1; }
}
@keyframes float {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-15px); }
}
@keyframes scanline {
  0% { transform: translateY(-100%); }
  100% { transform: translateY(0); }
}
@keyframes background-pan {
  0% { background-position: 0 0; }
  100% { background-position: 200px 200px; }
}
